<p class="muted">Immutable savings movements. Reverse a mistaken entry, then record the replacement if needed.</p>
<div class="row g-2 mb-3"><div class="col-sm-6"><label class="form-label" for="savings-from">History from</label><x-input id="savings-from" class="form-control" type="date" wire:model.live="savingsFrom" /></div><div class="col-sm-6"><label class="form-label" for="savings-to">History to</label><x-input id="savings-to" class="form-control" type="date" wire:model.live="savingsTo" /></div></div>
@php($entries=\Illuminate\Support\Facades\DB::table('savings_entries as e')->leftJoin('users as u','u.id','=','e.user_id')->select('e.*','u.name as administrator')->when($savingsFrom,fn($q)=>$q->where('business_date','>=',$savingsFrom))->when($savingsTo,fn($q)=>$q->where('business_date','<=',$savingsTo))->orderByDesc('e.id')->paginate(15,pageName:'savingsPage'))
@forelse($entries as $entry)<section class="detail-box mb-2"><div class="d-flex justify-content-between flex-wrap gap-2"><strong>#{{ $entry->id }} · {{ ucfirst($entry->type) }} · {{ $money($entry->amount) }}</strong><span>{{ $entry->business_date }}</span></div><p class="mb-1">{{ $entry->explanation }}</p><p class="small mb-1">{{ $money($entry->before_balance) }} → {{ $money($entry->after_balance) }} · {{ $entry->administrator??'Unknown administrator' }} · {{ $entry->created_at }}</p>@if($entry->reverses_id)<small>Reverses entry #{{ $entry->reverses_id }}</small>@elseif(\Illuminate\Support\Facades\DB::table('savings_entries')->where('reverses_id',$entry->id)->exists())<small>Reversed · original entry retained</small>@else<button class="btn btn-light btn-sm" wire:click="openSavings('reversal',{{ $entry->id }})">Reverse mistaken entry</button>@endif</section>@empty<p>No savings entries in this range.</p>@endforelse
{{ $entries->links() }}
